// HasWorkerInstance applies the HasEdge predicate on the "worker_instance" edge.
func HasWorkerInstance() predicate.JudgeWorkerCapability {
	return predicate.JudgeWorkerCapability(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, WorkerInstanceTable, WorkerInstanceColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasWorkerInstanceWith applies the HasEdge predicate on the "worker_instance" edge with a given conditions (other predicates).
func HasWorkerInstanceWith(preds ...predicate.JudgeWorkerInstance) predicate.JudgeWorkerCapability {
	return predicate.JudgeWorkerCapability(func(s *sql.Selector) {
		step := newWorkerInstanceStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasActivations applies the HasEdge predicate on the "activations" edge.
func HasActivations() predicate.JudgeWorkerCapability {
	return predicate.JudgeWorkerCapability(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, ActivationsTable, ActivationsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasActivationsWith applies the HasEdge predicate on the "activations" edge with a given conditions (other predicates).
func HasActivationsWith(preds ...predicate.ActivatedJudgeCapability) predicate.JudgeWorkerCapability {
	return predicate.JudgeWorkerCapability(func(s *sql.Selector) {
		step := newActivationsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.JudgeWorkerCapability) predicate.JudgeWorkerCapability {
	return predicate.JudgeWorkerCapability(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.JudgeWorkerCapability) predicate.JudgeWorkerCapability {
	return predicate.JudgeWorkerCapability(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.JudgeWorkerCapability) predicate.JudgeWorkerCapability {
	return predicate.JudgeWorkerCapability(sql.NotPredicates(p))
}
